      #sp .sp-step{display:flex;gap:.9rem;align-items:flex-start;padding:1rem 1.1rem;border-radius:13px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.1);margin-bottom:.7rem}
