DELL_RAM_NOTE = ("Every machine comes with <strong>16GB fitted</strong>. Want 32GB? Guide upgrade: <strong>+&pound;176</strong> on laptops and Micro desktops, <strong>+&pound;210</strong> on SFF/Tower desktops (2&times;16GB, fitted). "
                 "One honest heads-up: memory prices are moving unusually fast right now (the same AI data-centre demand behind <a href=\"/why-computer-prices-have-gone-up/\">rising computer prices</a>), so we confirm RAM upgrade pricing at quote time. "
                 "Note the Latitude 7000 series has soldered memory &mdash; it can&rsquo;t be upgraded later, so pick the size you&rsquo;ll ever need up front.")

def _model_details_band(slug):
    prefix = {"refurbished-dell-latitude-3000": "latitude-3", "refurbished-dell-latitude-5000": "latitude-5",
              "refurbished-dell-latitude-7000": "latitude-7", "refurbished-dell-optiplex-3000": "optiplex-3",
              "refurbished-dell-optiplex-5000": "optiplex-5", "refurbished-dell-optiplex-7000": "optiplex-7"}.get(slug)
    if not prefix:
        return ""
    rows = []
    for mid, kind, series, name, meta, price, href, cpu_disp, threads, gen in DELL_MACHINES:
        if not mid.startswith(prefix):
            continue
        port = DELL_PORTS.get(mid, "")
        port_row = f'<tr><th>Screen connections</th><td>{port}</td></tr>' if port else ''
        first = meta.split(' &middot; ')[0]
        label = ('Display' if kind == 'laptop' else 'Form factors')
        rows.append(f'''          <div class="mdet" id="{mid}">
            <h3>{name} <span class="mdet__price mono">guide &pound;{price}</span></h3>
            <div class="cmp-wrap"><table class="cmp-table"><tbody>
              <tr><th>{label}</th><td>{first}</td></tr>
              <tr><th>Processor</th><td>{cpu_disp}</td></tr>
              <tr><th>Memory</th><td>{('16GB soldered &mdash; cannot be upgraded later; 32GB units available to order, so pick the size you&rsquo;ll ever need' if mid.startswith('latitude-7') else ('16GB fitted (dual-channel, two slots) &middot; 32GB upgrade guide +&pound;176' if kind=='laptop' else '16GB fitted (two slots) &middot; 32GB upgrade guide +&pound;176 (Micro) or +&pound;210 (SFF/Tower)'))}</td></tr>
              <tr><th>Storage</th><td>New 1TB Samsung 990 PRO NVMe &middot; upgrade to 2TB +&pound;185 or 4TB +&pound;420 (guide)</td></tr>
              {port_row}
              <tr><th>Included</th><td>Windows 11 Home or Pro set up, data moved across, 12-month guarantee (5 years on a support plan)</td></tr>
            </tbody></table></div>
            <p class="mdet__cta"><a class="button primary" href="/dell-hardware/?model={mid}#pick">Check availability &amp; get a quote &#8594;</a></p>
          </div>''')
    ram_note = f'<p class="lede lede--center" data-reveal>{DELL_RAM_NOTE}</p>' if DELL_RAM_NOTE else ''
    return ('''    <section class="section" aria-label="Model details and upgrades">
      <div class="wrap" data-reveal>
        <div class="section-head">
          <p class="eyebrow eyebrow--center mono">// FULL MODEL DETAILS &amp; UPGRADES</p>
          <h2 class="section-title section-title--center" data-title>Every model in detail<span class="title-underline title-underline--center"></span></h2>
''' + ram_note + '''        </div>
''' + "\n".join(rows) + '''
      </div>
      <style>
        .mdet{max-width:860px;margin:0 auto 1.6rem}
        .mdet h3{display:flex;align-items:baseline;justify-content:space-between;gap:1rem;flex-wrap:wrap;margin:0 0 .6rem}
        .mdet__price{color:var(--cyan-soft);font-size:.78rem;letter-spacing:.05em;text-transform:uppercase}
        .mdet__cta{margin:.8rem 0 0;text-align:right}
      </style>
    </section>''')

def _refurb_reserve_band(slug):
    """Per-series 'pick & reserve' band: quick links into the /dell-hardware/#pick tool
    with the right model preselected. Injected on refurbBands sales pages."""
    prefix = {"refurbished-dell-latitude-3000": "latitude-3", "refurbished-dell-latitude-5000": "latitude-5",
              "refurbished-dell-latitude-7000": "latitude-7", "refurbished-dell-optiplex-3000": "optiplex-3",
              "refurbished-dell-optiplex-5000": "optiplex-5", "refurbished-dell-optiplex-7000": "optiplex-7"}.get(slug)
    if not prefix:
        return ""
    links = "".join(
        f'          <a class="rsv__m" href="/dell-hardware/?model={mid}#pick"><span class="rsv__name">{name}</span><span class="rsv__price mono">guide &pound;{price}</span></a>\n'
        for mid, kind, series, name, meta, price, href, cpu_disp, threads, gen in DELL_MACHINES if mid.startswith(prefix))
    return ('''    <section class="section section--alt" aria-label="Pick and reserve">
      <div class="wrap" data-reveal>
        <div class="section-head">
          <p class="eyebrow eyebrow--center mono">// READY? CHECK AVAILABILITY IN A MINUTE</p>
          <h2 class="section-title section-title--center" data-title>Check availability &amp; get your quote<span class="title-underline title-underline--center"></span></h2>
          <p class="lede lede--center">Choose a model below, add your details, and your pick goes straight to the team &mdash; we&rsquo;ll confirm availability and your exact quote shortly (stock varies, so we may suggest the nearest equivalent). <strong>Guide prices</strong>, no payment online, no obligation &mdash; and you can add accessories to the same quote.</p>
        </div>
        <div class="rsv">
''' + links + '''        </div>
      </div>
      <style>
        .rsv{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:.9rem;max-width:900px;margin:0 auto}
        .rsv__m{display:flex;flex-direction:column;gap:.25rem;padding:1rem 1.1rem;background:var(--glass);border:1px solid var(--line);
          border-radius:14px;text-decoration:none;color:inherit;transition:border-color .2s ease,transform .2s ease}
        .rsv__m:hover{border-color:rgba(29,151,227,.6);transform:translateY(-2px)}
        .rsv__name{font-family:var(--font-display);font-weight:600;font-size:1.02rem}
        .rsv__price{color:var(--cyan-soft);font-size:.72rem;letter-spacing:.05em;text-transform:uppercase}
      </style>
    </section>''')

def build_new_page(d):
    faqs = [(f['q'], f['a']) if isinstance(f, dict) else tuple(f) for f in d['faqs']]
    _blocks = [_sec_block(s, i) for i, s in enumerate(d['sections'])]
    # help-ASAP funnel: problem-intent pages get the SOS band right after section 1
    if _wants_sos_band(d['slug']) and len(_blocks) > 1:
        _blocks.insert(1, bp.SOS_BAND)
    # learning funnel: gentle pages promote the free courses at the end
    if _wants_courses_band(d['slug']):
        _blocks.append(bp.COURSES_BAND)
    # AEO comparison table: high-value "vs"/"which" pages get an at-a-glance table after section 1
    _cmp = DELL_COMPARE_TABLES.get(d['slug'])
    if _cmp:
        _cmp_head, _cmp_html = _cmp
        _cmp_block = f'''    <section class="section section--alt" aria-label="At a glance">
      <div class="wrap" data-reveal>
        <div class="section-head"><h2 class="section-title section-title--center">{_cmp_head}<span class="title-underline title-underline--center"></span></h2></div>
        {_cmp_html}
      </div>
    </section>'''
        _blocks.insert(1 if len(_blocks) > 1 else len(_blocks), _cmp_block)
    if d.get('refurbBands'):
        _blocks.append(REFURB_PRICE_RISE_BAND)
        _blocks.append(REFURB_SUPPORT_BAND)
        _blocks.append(_model_details_band(d['slug']))
        _blocks.append(_refurb_reserve_band(d['slug']))
    sections = "\n".join(_blocks)
    cross = ""
    if d.get('crossLinksHtml'):
        cross = f'''    <section class="section" aria-label="Related">
      <div class="wrap prose" data-reveal>
        <p class="eyebrow mono">// RELATED</p>
{d['crossLinksHtml']}
      </div>
    </section>'''
    _hubbox = ""
    if d['slug'] in ("outlook-problems",):
        _hubbox = '''    <section class="section" aria-label="Search" style="padding-top:0">
      <div class="wrap" style="display:flex;justify-content:center">
        <button type="button" class="search-box" data-search-open>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/></svg>
          <span class="search-box__txt">Search all Outlook fixes &amp; the whole site&hellip;</span>
          <kbd>/</kbd>
        </button>
      </div>
    </section>'''
    _hub = _pack_hub(d['slug'])
    _bch = bp.bc_sub(_hub[0], '/' + _hub[1] + '/', d['crumbName']) if _hub else bc(d['crumbName'])
    content = "\n".join([
      hero(_bch, d['eyebrow'], d['h1'], hero_trust(d['lede']),
           cta1=tuple(d['primaryCta']), cta2=tuple(d['secondaryCta']), chips=list(d['chips']),
           scene=HERO_SCENES.get(_PACK_SCENE.get(d['slug']))),
      _hubbox,
      sections,
      cross,
      faq_html(faqs),
      cta(d['ctaHead'], d['ctaSub'], primary=tuple(d['primaryCta']), secondary=tuple(d['secondaryCta'])),
    ])
    def schema(s, _d=d, _faqs=faqs, _hub=_hub):
        _c = bp.crumb_sub(s, _hub[0], _hub[1], _d['crumbName']) if _hub else crumb(s, _d['crumbName'])
        nodes = [_c, webpage(s, _d['crumbName'], _d['metaDesc'])]
        if _d.get('schemaKind') == 'service':
            _area = bp.WORLDWIDE_AREA if _d.get('worldwide') else None
            nodes.append(service(s, _d.get('serviceName', _d['crumbName']), _d['metaDesc'], _d.get('serviceName', _d['crumbName']), area=_area))
        if _d.get('howToSteps'):
            nodes.append(bp.howto_node(s, _d.get('howToName', _d['crumbName']), [(st['name'], st['text']) for st in _d['howToSteps']]))
        if _d.get('productOffer'):
            po = _d['productOffer']
            nodes.append({"@type": "Product", "@id": SITE + "/" + s + "/#product",
                          "name": po['name'], "description": po['description'],
                          "brand": {"@type": "Brand", "name": "Dell"},
                          "itemCondition": "https://schema.org/RefurbishedCondition",
                          "category": po.get('category', 'Refurbished computer hardware'),
                          "additionalProperty": [{"@type": "PropertyValue", "name": n, "value": v} for n, v in po.get('props', [])],
                          "offers": {"@type": "AggregateOffer", "priceCurrency": "GBP", "lowPrice": po['lowPrice'],
                                     "availability": "https://schema.org/InStock", "url": SITE + "/" + s + "/" + po.get('offerAnchor', ''),
                                     "seller": {"@type": "Organization", "name": "365 Techies"}},
                          "image": SITE + "/og-image.jpg", "url": SITE + "/" + s + "/"})
        nodes.append(faqpage(s, _faqs))
        return graph(nodes)
    add(slug=d['slug'], title=d['title'], desc=d['metaDesc'], og_title=d['ogTitle'], schema=schema, content=content)

